'use strict';
const assert=require('node:assert/strict'),M=require('../../releases/v463/lts-expense-presentation-model.js'),Debt=require('../../releases/v463/lts-v463-debt-model.js');
const cell=(category,macro,payment,gross,comp=0)=>({macrogroup:macro,group_name:'Grupo preservado',category,payment,gross,compensations:comp,net:gross-comp,rows:1,property:'__missing__',person:'__missing__',center_cost:'__missing__',is_tax:false});
const cells=[cell('Saúde','Saúde','card',100),cell('Saúde','Saúde','account',20),cell('Restaurantes','Alimentação','card',50),cell('iFood','Alimentação','account',25),cell('Saúde','Saúde','card',0,10)];
const p={version:'expense-presentation-v353',period:{from:'2020-01-01',to:'2020-01-31'},summary:{gross:195,compensations:10,net:185,rows:5},cells,dimensions:{property:[],person:[],center_cost:[]}},source=JSON.stringify(p);
assert.equal(M.build(p).summary.net,185);assert.equal(M.build(p,{payment:'card'}).summary.net,140);assert.equal(M.build(p,{payment:'account'}).summary.net,45);
assert.equal(M.build(p,{payment:'card'}).nodes.find(x=>x.name==='Saúde').net,90);
const food=M.build(p).nodes.find(x=>x.name==='Alimentação');assert.deepEqual(food.children.map(x=>x.name),['Restaurantes','iFood']);assert(food.children.every(x=>!x.children.length));
assert.equal(M.build(p).nodes.find(x=>x.name==='Saúde').children.length,0);assert.equal(JSON.stringify(p),source);
assert.throws(()=>M.build(p,{payment:'unknown'}));const legacy=structuredClone(p);legacy.cells.forEach(c=>delete c.payment);assert.equal(M.build(legacy).paymentAvailable,false);assert.throws(()=>M.build(legacy,{payment:'card'}));
const principal=1200,rate=.01,n=12,payment=Math.round(principal*rate/(1-Math.pow(1+rate,-n))*100)/100;
function loan(){return{id:'volvo',confidence:'documented_contract',total_events:n,installment:payment,confirmed_paid_installments:2,remaining_events:10,unconfirmed_past_events:0,realized_rows:[1,2].map(i=>({status:'paid',installment_number:i,paid_date:`2020-0${i}-05`,due_date:`2020-0${i}-05`,source_ref:'bank-'+i,payment_basis:'validated_existing_bank_identity',paid_amount:payment,scheduled_amount:payment})),schedule_rows:Array.from({length:10},(_,i)=>({installment_number:i+3,due_date:`2020-${String(i+3).padStart(2,'0')}-05`,amount:payment}))};}
const asset={documented_financed_balance:principal},l=loan(),before=JSON.stringify(l),x=Debt.estimate(asset,l,'2020-02-10');assert(x);assert.equal(x.asOf,'2020-02-05');assert.equal(x.paidCount,2);assert(x.balance<principal);assert(x.balance>principal-payment*2,'Do not subtract the interest-bearing full payments from principal');assert(Math.abs(x.inferredMonthlyRate-rate)<.00001);assert.equal(JSON.stringify(l),before);
for(const mutate of [q=>q.realized_rows[1].source_ref=q.realized_rows[0].source_ref,q=>q.realized_rows[1].paid_amount=1,q=>q.realized_rows[1].installment_number=3,q=>q.unconfirmed_past_events=1,q=>q.schedule_rows[0].amount=1,q=>q.realized_rows[1].paid_date='2021-01-01',q=>q.current_documentary_debt_balance=500]){const q=loan();mutate(q);if(q.current_documentary_debt_balance)q.current_debt_as_of='2020-02-10';assert.equal(Debt.estimate(asset,q,'2020-02-10'),null);}
assert.equal(Debt.estimate({documented_financed_balance:null},l,'2020-02-10'),null);
console.log(JSON.stringify({pass:true,channel_totals_and_signed_refunds:true,original_categories_and_rows_preserved:true,no_false_legacy_channel_split:true,dated_loan_estimate_uses_only_proved_payments:true,loan_unknown_duplicate_partial_future_or_documented_cases_guarded:true}));
